/// <summary>
/// UI builder for the @TaxTransactionInquiry:HeaderNote report dialog.
/// Customizes dialog fields (lookups, dependent fields, events).
/// </summary>
public class ConDemoCustGroupReportUIBuilder extends SrsReportDataContractUIBuilder
{
}

Method.Source:
/// <summary>
/// Builds the dialog and customizes its fields.
/// </summary>
public void build()
{
    ConDemoCustGroupReportContract contract;
    DialogField                    custGroupField;

    super();

    contract       = this.dataContractObject() as ConDemoCustGroupReportContract;
    custGroupField = this.bindInfo().getDialogField(contract, methodStr(ConDemoCustGroupReportContract, parmCustGroup));
    custGroupField.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(ConDemoCustGroupReportUIBuilder, custGroupLookup), this);
}

/// <summary>
/// Restricts the customer-group lookup to the groups that have payment terms.
/// </summary>
/// <param name = "_control">The dialog control being looked up.</param>
private void custGroupLookup(FormStringControl _control)
{
    SysTableLookup       sysTableLookup = SysTableLookup::newParameters(tableNum(CustGroup), _control);
    Query                query          = new Query();
    QueryBuildDataSource qbds           = query.addDataSource(tableNum(CustGroup));

    sysTableLookup.addLookupfield(fieldNum(CustGroup, CustGroup));
    sysTableLookup.addLookupfield(fieldNum(CustGroup, Name));
    qbds.addRange(fieldNum(CustGroup, PaymTermId)).value(SysQuery::valueNotEmptyString());
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
